mapper.select:
SELECT id, hot_id, hot_value, `rank`, recorded_at
FROM (
    SELECT id, hot_id, hot_value, `rank`, recorded_at
    FROM hot_history
    WHERE hot_id = #{hotId}
      AND recorded_at >= #{since}
    ORDER BY recorded_at DESC
    LIMIT #{limit}
) recent_history
ORDER BY recorded_at ASC
